class BookManagement:
    def __init__(self):
        self._inventory = {}

    def add_book(self, title, quantity=1):
        if title in self._inventory:
            self._inventory[title] += quantity
        else:
            self._inventory[title] = quantity

    def remove_book(self, title, quantity):
        if not self._can_remove_book(title, quantity):
            raise ValueError("Cannot remove book: insufficient quantity or book not in inventory")
        self._inventory[title] -= quantity
        if self._inventory[title] == 0:
            del self._inventory[title]

    def view_inventory(self):
        return dict(self._inventory)

    def view_book_quantity(self, title):
        if title not in self._inventory:
            return 0
        return self._inventory[title]

    def _can_remove_book(self, title, quantity):
        return title in self._inventory and self._inventory[title] >= quantity
